import re
from typing import Dict

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    """
    Parse an INI file and return a dictionary of sections and their key-value pairs.

    :param text: The INI file content as a string
    :return: A dictionary of sections and their key-value pairs
    """
    sections: Dict[str, Dict[str, str]] = {}
    default_section: Dict[str, str] = {}
    current_section: Dict[str, str] = default_section
    current_key: str = ""
    current_value: str = ""

    for line in text.splitlines():
        # Remove leading and trailing whitespace
        line = line.strip()

        # Ignore empty lines and comments
        if not line or line[0] in [";", "#"]:
            continue

        # Check for section headers
        match = re.match(r"\s*\[(.*?)\]\s*", line)
        if match:
            section_name = match.group(1)
            if section_name == "DEFAULT":
                current_section = default_section
            else:
                current_section = sections.setdefault(section_name, {})
            current_key = ""
            current_value = ""
            continue

        # Check for key-value pairs
        match = re.match(r"\s*(\S+)\s*([:=])\s*(.*)", line)
        if match:
            key = match.group(1).strip().lower()
            value = match.group(3).strip()
            current_key = key
            current_value = value
            current_section[key] = value
            continue

        # Check for continuation lines
        if line and current_key:
            current_value += "\n" + line.strip()
            current_section[current_key] = current_value
            continue

        # Raise an error for malformed lines
        raise ValueError("Malformed line: " + line)

    # Interpolate values
    def interpolate(value: str, section: Dict[str, str]) -> str:
        def replace(match: re.Match) -> str:
            ref = match.group(1)
            if ":" in ref:
                section_name, key = ref.split(":", 1)
                if section_name not in sections:
                    raise KeyError(f"Section '{section_name}' not found")
                section_ref = sections[section_name]
                if key not in section_ref:
                    raise KeyError(f"Key '{key}' not found in section '{section_name}'")
                return section_ref[key]
            else:
                if ref not in section:
                    raise KeyError(f"Key '{ref}' not found")
                return section[ref]

        while True:
            new_value = re.sub(r"\${(.*?)}", replace, value)
            if new_value == value:
                break
            value = new_value

        return value

    for section_name, section in sections.items():
        for key, value in section.items():
            # Check for reference cycles
            try:
                sections[section_name][key] = interpolate(value, {**default_section, **section})
            except RecursionError:
                raise ValueError("Reference cycle detected")

    return {section_name: section for section_name, section in sections.items() if section_name != "DEFAULT"}
